delete
from DIS_PROD_BONUSPLAN

    DATA_STATUS ='E'

        and  PROD_ID = #{prodId,jdbcType=VARCHAR}


        and BONUS_MODE = #{bonusPlanId,jdbcType=VARCHAR}


