mapper.select:
SELECT
dpb.BONUS_PLAN_ID, dpb.PROD_ID, dpb.BONUS_MODE,
dpb.SETT_DATE, dpb.PAYMENT_DATE, dpb.ACHIEVEMENT,
dpb.EXCESS_ACHIEVEMENT_PROP, dpb.ACHIEVEMENT_BASIS,
dpb.ACHIEVEMENT_BASIS_PROP, dpb.DATA_STATUS, dpb.DATA_SOURCE,
dpb.CREATE_USER, dpb.CREATE_TIME, dpb.UPDATE_USER,
dpb.UPDATE_TIME, dpb.CREATE_DEPT,
TO_CHAR(dpb.SETT_DATE,'yyyy-mm-dd') settDateStr,
TO_CHAR(dpb.PAYMENT_DATE,'yyyy-mm-dd') paymentDateStr,
TO_CHAR(NVL(dpb.Update_Time,dpb.Create_Time),'yyyy-mm-dd hh24:mi:ss') updateDateStr,
rpi.prod_name prodName
FROM DIS_PROD_BONUSPLAN dpb
LEFT JOIN REP_PROD_INFO rpi ON rpi.PROD_ID = dpb.PROD_ID and rpi.STATUS = 'E' WHERE 1=1

    AND dpb.DATA_STATUS IN

        #{item}



    AND dpb.PROD_ID IN

        #{item}



    AND dpb.PROD_ID IN

        #{item}



    AND dpb.BONUS_MODE IN

        #{item}



    AND to_char(dpb.SETT_DATE,'yyyy-mm-dd') >= #{settDateBegin,jdbcType=VARCHAR}


    AND to_char(dpb.SETT_DATE,'yyyy-mm-dd') <= #{settDateEnd,jdbcType=VARCHAR}



    AND to_char(dpb.PAYMENT_DATE,'yyyy-mm-dd') >= #{paymentDateBegin,jdbcType=VARCHAR}


    AND to_char(dpb.PAYMENT_DATE,'yyyy-mm-dd') <= #{paymentDateEnd,jdbcType=VARCHAR}


order by NVL(dpb.UPDATE_TIME,dpb.CREATE_TIME) desc

select dpb.BONUS_PLAN_ID, dpb.PROD_ID, dpb.BONUS_MODE, dpb.SETT_DATE, dpb.PAYMENT_DATE, dpb.ACHIEVEMENT, dpb.EXCESS_ACHIEVEMENT_PROP, dpb.ACHIEVEMENT_BASIS, dpb.ACHIEVEMENT_BASIS_PROP, dpb.DATA_STATUS, dpb.DATA_SOURCE, dpb.CREATE_USER, dpb.CREATE_TIME, dpb.UPDATE_USER, dpb.UPDATE_TIME, dpb.CREATE_DEPT from DIS_PROD_BONUSPLAN dpb where dpb.PROD_ID = #{prodId,jdbcType=VARCHAR} and dpb.BONUS_MODE = '02'
AND dpb.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}
and rownum <= 1

select dpb.BONUS_PLAN_ID, dpb.PROD_ID, dpb.BONUS_MODE, dpb.SETT_DATE, dpb.PAYMENT_DATE, dpb.ACHIEVEMENT, dpb.EXCESS_ACHIEVEMENT_PROP, dpb.ACHIEVEMENT_BASIS, dpb.ACHIEVEMENT_BASIS_PROP, dpb.DATA_STATUS, dpb.DATA_SOURCE, dpb.CREATE_USER, dpb.CREATE_TIME, dpb.UPDATE_USER, dpb.UPDATE_TIME, dpb.CREATE_DEPT from DIS_PROD_BONUSPLAN dpb where DATA_STATUS !='D'
and dpb.PROD_ID = #{prodId,jdbcType=VARCHAR}
and to_char(dpb.SETT_DATE,'yyyy-mm-dd') = #{settDateStr,jdbcType=VARCHAR}
and rownum <= 1

select distinct PROD_ID id, PROD_NAME text from REP_PROD_INFO where STATUS='E' and IS_GRADE = '02'
and (PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or PROD_NAME like '%' || #{search, jdbcType=VARCHAR} || '%')
and PROD_ID = #{initValue}
union all select distinct rp1.PROD_ID id, concat(rp2.PROD_NAME,concat('(',concat(rp1.PROD_NAME,')'))) text from REP_PROD_INFO rp1 left join REP_PROD_INFO rp2 on rp1.P_PROD_ID = rp2.PROD_ID where rp1.STATUS='E' and rp2.IS_GRADE = '01'
and (rp1.PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or rp2.PROD_NAME like '%' || #{search, jdbcType=VARCHAR} || '%')
and rp1.PROD_ID = #{initValue}

select count(1) from( select dpb.BONUS_PLAN_ID, dpb.PROD_ID, dpb.BONUS_MODE, dpb.SETT_DATE, dpb.PAYMENT_DATE, dpb.ACHIEVEMENT, dpb.EXCESS_ACHIEVEMENT_PROP, dpb.ACHIEVEMENT_BASIS, dpb.ACHIEVEMENT_BASIS_PROP, dpb.DATA_STATUS, dpb.DATA_SOURCE, dpb.CREATE_USER, dpb.CREATE_TIME, dpb.UPDATE_USER, dpb.UPDATE_TIME, dpb.CREATE_DEPT from DIS_PROD_BONUSPLAN dpb where dpb.PROD_ID = #{prodId,jdbcType=VARCHAR} and dpb.BONUS_MODE = '02'
AND dpb.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}
) a
